#!/usr/bin/env python3
"""The declared FalloutPrefs.ini of the platform: one generated file, from the exe's launcher gate and the adapter identity (L5).

  gen_prefs_ini.py <required.tsv> <out.inc> --ident <ident.bin> [--ident <ident.bin> ...]

required.tsv is the second output of prefs_settings.py: the settings of the prefs collection that the exe's launcher gate reads
(key, section, object, gate function). The gate compares exactly one setting with the Description field of
IDirect3D9::GetAdapterIdentifier(0, 0); so the file holds that one key, whose value is the Description the platform's d3d9 front
end answers on the declared machine. Every other key is absent and the exe uses its built-in defaults (owner rule).

--ident: the render front end's adapter identity image for one profile (ident_handheld.bin, ident_docked.bin from render/d3d9's
gen_env step): the 1100-byte D3DADAPTER_IDENTIFIER9 that GetAdapterIdentifier(0,0) fills (Driver[512], Description[512] at offset
512, DeviceName[32], ...). The Description is the bytes at 512..1023 up to the first NUL. All images given must be byte-equal (the
profiles differ only in the mode). No copy of the string lives in this tree: the include is generated.

Refusals (exit status 2, no output): required.tsv not exactly one row; no `--ident`; an unreadable image or one that is not 1100
bytes; images that differ; an empty Description, one without a NUL in its 512 bytes, or with a non-printable byte.

Output: platform/win32/declared_files.cpp includes the rows `{ dir, name, text, size }`; dir is relative to CSIDL_PERSONAL.
PROFILE_DIR is the exe's profile directory, "My Games\\FalloutNV\\" (SHGetFolderPathA(CSIDL_PERSONAL) + "\\My Games\\" + "FalloutNV\\",
the exe's own Fallout.ini creation). The ini text uses CRLF, as WritePrivateProfileStringA writes it.
"""
import os, sys

PROFILE_DIR = "My Games\\FalloutNV\\"
FILE_NAME = "FalloutPrefs.ini"


def die(msg):
    sys.stderr.write("gen_prefs_ini: " + msg + "\n")
    sys.exit(2)


IDENT_SIZE = 1100
DESC_OFF, DESC_LEN = 512, 512


def read_ident(path):
    try:
        raw = open(path, "rb").read()
    except OSError as e:
        die("cannot read %s: %s" % (path, e.strerror))
    if len(raw) != IDENT_SIZE:
        die("%s: an adapter identity image is %d bytes, got %d" % (path, IDENT_SIZE, len(raw)))
    return raw


def adapter_description(raw, path):
    field = raw[DESC_OFF:DESC_OFF + DESC_LEN]
    n = field.find(b"\0")
    if n < 0:
        die("%s: the Description has no NUL in its %d bytes" % (path, DESC_LEN))
    text = field[:n]
    if not text or any(not (32 <= c < 127) for c in text):
        die("%s: Description must be non-empty printable ASCII" % path)
    return text.decode("ascii")


def c_text(s):
    out = []
    for c in s:
        out.append("\\r" if c == "\r" else "\\n" if c == "\n" else "\\%03o" % ord(c) if c in '"\\?' else c)
    return "".join(out)


def main(argv):
    idents, args, i = [], [], 0
    while i < len(argv):
        if argv[i] == "--ident":
            if i + 1 >= len(argv):
                die("--ident needs a path")
            idents.append(argv[i + 1])
            i += 2
        else:
            args.append(argv[i])
            i += 1
    if len(args) != 2 or not idents:
        die("usage: gen_prefs_ini.py <required.tsv> <out.inc> --ident <ident.bin> [--ident ...]")
    req, out = args
    try:
        lines = [l for l in open(req, encoding="utf-8").read().split("\n") if l and not l.startswith("#")]
    except OSError as e:
        die("cannot read %s: %s" % (req, e.strerror))
    rows = [l.split("\t") for l in lines]
    if len(rows) != 1 or len(rows[0]) != 4 or not rows[0][0] or not rows[0][1]:
        die("%s: exactly one (key, section, object, gate) row expected, got %d" % (req, len(rows)))
    key, sec = rows[0][0], rows[0][1]
    if any(c in key + sec for c in "=[]\r\n;"):
        die("%s: key or section holds an INI delimiter" % req)
    images = [(p, read_ident(p)) for p in idents]
    if any(img != images[0][1] for _, img in images):
        die("the adapter identity images are not byte-equal")
    desc = adapter_description(images[0][1], images[0][0])
    text = "[%s]\r\n%s=%s\r\n" % (sec, key, desc)
    body = '{ "%s", "%s", "%s", %d },\n' % (c_text(PROFILE_DIR), FILE_NAME, c_text(text), len(text))
    os.makedirs(os.path.dirname(os.path.abspath(out)), exist_ok=True)
    tmp = out + ".tmp"
    with open(tmp, "w") as fh:
        fh.write("/* generated by platform/manifest/gen_prefs_ini.py: the declared FalloutPrefs.ini (launcher gate setting = adapter Description) */\n")
        fh.write(body)
    os.replace(tmp, out)


if __name__ == "__main__":
    main(sys.argv[1:])
